<script setup lang="ts">defineProps<{meta:any}>();defineEmits<{change:[page:number]}>()</script><template><div class="pagination" v-if="meta"><button :disabled="meta.current_page<=1" @click="$emit('change',meta.current_page-1)">Anterior</button><span>Página {{meta.current_page}} de {{meta.last_page}} — {{meta.total}} registros</span><button :disabled="meta.current_page>=meta.last_page" @click="$emit('change',meta.current_page+1)">Próxima</button></div></template>
